import { renderLiteral } from "../utils/render-literal"
import type { SurfaceInventory } from "./build-inventory"

export function renderInventory(
  inventory: Record<string, SurfaceInventory>,
  typescript: boolean
) {
  return [
    "// Generated by `pliantui scan` from your app's source.",
    "// Don't edit it by hand. Run the command again instead.",
    "",
    `export const inventory = ${renderLiteral(inventory)}${typescript ? " as const" : ""}`,
    "",
  ].join("\n")
}
